import type {
  ProviderBCommitBatch,
  ProviderBStorage,
  Reservation,
  Service,
  ServiceResponse,
  Stock,
} from "./types";
import { error, parseReservationCommand, reservationResponse } from "./reservation";
import {
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeCanonicalDecimal,
  isRecord,
  isRevision,
  toProviderBReservationRow,
  toProviderBStockRow,
} from "./validation";

type ProviderBReadOutcome =
  | Readonly<{ kind: "found"; value: unknown }>
  | Readonly<{ kind: "missing" }>
  | Readonly<{ kind: "unavailable" }>;

function decodeReadOutcome(value: unknown): ProviderBReadOutcome {
  if (!isRecord(value) || typeof value.ok !== "boolean") return { kind: "unavailable" };
  if (value.ok) return { kind: "found", value: value.value };
  if (!isRecord(value.error)) return { kind: "unavailable" };
  if (value.error.reason === "NO_SUCH_KEY") return { kind: "missing" };
  return { kind: "unavailable" };
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<
  | Readonly<{ kind: "found"; stock: Stock }>
  | Readonly<{ kind: "missing" }>
  | Readonly<{ kind: "unavailable" }>
> {
  const outcome = decodeReadOutcome(await storage.read({ collection: "inventory", key: sku }));
  if (outcome.kind !== "found") return outcome;
  const stock = decodeProviderBStockRow(outcome.value, sku);
  return stock === undefined ? { kind: "unavailable" } : { kind: "found", stock };
}

async function readReservation(storage: ProviderBStorage, reservationId: string): Promise<
  | Readonly<{ kind: "found"; reservation: Reservation }>
  | Readonly<{ kind: "missing" }>
  | Readonly<{ kind: "unavailable" }>
> {
  const outcome = decodeReadOutcome(await storage.read({ collection: "reservations", key: reservationId }));
  if (outcome.kind !== "found") return outcome;
  const reservation = decodeProviderBReservationRow(outcome.value, reservationId);
  return reservation === undefined ? { kind: "unavailable" } : { kind: "found", reservation };
}

function availabilityResponse(stock: Stock): ServiceResponse {
  return {
    status: 200,
    body: {
      sku: stock.sku,
      totalUnits: stock.totalUnits,
      reservedUnits: stock.reservedUnits,
      availableUnits: stock.totalUnits - stock.reservedUnits,
    },
  };
}

function buildBatch(stock: Stock, reservation: Reservation, nextRevision: number): ProviderBCommitBatch {
  return {
    expectedRevisionText: encodeCanonicalDecimal(stock.revision),
    stockRow: toProviderBStockRow({
      ...stock,
      reservedUnits: stock.reservedUnits + reservation.quantity,
      revision: nextRevision,
    }),
    reservationRow: toProviderBReservationRow(reservation),
    outboxRows: [{
      key: "reservation.created:" + reservation.reservationId,
      category: "reservation",
      name: "created",
      payload: {
        bookingKey: reservation.reservationId,
        itemKey: reservation.sku,
        unitsText: encodeCanonicalDecimal(reservation.quantity),
      },
    }],
  };
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseReservationCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      try {
        if (command.op === "getAvailability") {
          const stockOutcome = await readStock(storage, command.sku);
          if (stockOutcome.kind === "missing") return error(404, "stock_not_found");
          if (stockOutcome.kind === "unavailable") return error(500, "storage_unavailable");
          return availabilityResponse(stockOutcome.stock);
        }

        const reservationOutcome = await readReservation(storage, command.reservationId);
        if (reservationOutcome.kind === "unavailable") return error(500, "storage_unavailable");
        if (command.op === "getReservation") {
          return reservationOutcome.kind === "found"
            ? reservationResponse(200, reservationOutcome.reservation)
            : error(404, "reservation_not_found");
        }
        if (reservationOutcome.kind === "found") {
          return reservationOutcome.reservation.sku === command.sku &&
            reservationOutcome.reservation.quantity === command.quantity
            ? reservationResponse(200, reservationOutcome.reservation)
            : error(409, "reservation_conflict");
        }

        const stockOutcome = await readStock(storage, command.sku);
        if (stockOutcome.kind === "missing") return error(404, "stock_not_found");
        if (stockOutcome.kind === "unavailable") return error(500, "storage_unavailable");
        if (stockOutcome.stock.totalUnits - stockOutcome.stock.reservedUnits < command.quantity) {
          return error(409, "insufficient_stock");
        }

        const nextRevision = stockOutcome.stock.revision + 1;
        if (!isRevision(nextRevision)) return error(500, "storage_unavailable");
        const reservation: Reservation = {
          reservationId: command.reservationId,
          sku: command.sku,
          quantity: command.quantity,
        };
        const outcome = await storage.commitBatch(buildBatch(stockOutcome.stock, reservation, nextRevision));
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

